package com.nequard.alerts;
import com.nequard.auth.OrganizationAccessService;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/alerts") public class AlertController{private final AlertRepository repo;private final OrganizationAccessService access;public AlertController(AlertRepository r,OrganizationAccessService a){repo=r;access=a;}@GetMapping public List<Alert> all(Authentication a,@RequestParam(defaultValue="OPEN")String status){UUID org=access.currentOrganization(a);return access.isSuperAdmin(a)&&org==null?repo.findByStatusOrderByCreatedAtDesc(status):repo.findByOrganizationIdAndStatusOrderByCreatedAtDesc(org,status);}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','NETWORK_ENGINEER','NOC_OPERATOR')") public ResponseEntity<?> create(Authentication a,@RequestBody Alert alert){try{UUID org=access.requireOrganization(a,alert.getOrganizationId());alert.setOrganizationId(org);return ResponseEntity.status(201).body(repo.save(alert));}catch(Exception e){return ResponseEntity.status(403).body(Map.of("error",e.getMessage()));}}@PatchMapping("/{id}/acknowledge") public ResponseEntity<?> acknowledge(Authentication a,@PathVariable UUID id){return repo.findById(id).filter(x->access.canAccess(a,x.getOrganizationId())).map(x->{x.setStatus("ACKNOWLEDGED");return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());}}